INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(80181649, '"A Case for K9"', '“K9刑侦案件”', '“Case of K９”', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「K9」怪兽加入手卡。 ②：对方把手卡·墓地的怪兽的效果发动的回合，自己场上的「K9」怪兽的攻击力上升900。 ③：魔法与陷阱区域的这张卡被效果破坏的场合才能发动。从自己的卡组·墓地把1张「K9」速攻魔法卡在自己场上盖放。'),
(34541863, '"A" Cell Breeding Device', '「A」细胞增殖装置', '「A」細胞増殖装置', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每次自己的准备阶段给对方场上表侧表示存在的1只怪兽放置1个A指示物。'),
(64163367, '"A" Cell Incubator', '「A」细胞培养装置', '「A」細胞培養装置', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每次从场上A指示物被取除，给这张卡放置1个A指示物。这张卡被破坏时，这张卡放置的全部A指示物给场上表侧表示存在的怪兽放置。'),
(91231901, '"A" Cell Recombination Device', '「A」细胞重组装置', '「A」細胞組み換え装置', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。从卡组把1只「外星」怪兽送去墓地，送去墓地的怪兽的等级数量的A指示物给作为对象的怪兽放置。 ②：自己主要阶段把墓地的这张卡除外才能发动。从卡组把1只「外星」怪兽加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(73262676, '"A" Cell Scatter Burst', '「A」细胞散布爆弹', '「A」細胞散布爆弾', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「外星」的怪兽发动。选择的怪兽破坏，那只怪兽等级的数量的A指示物在对方场上表侧表示存在的怪兽放置。'),
(98319530, '"Infernoble Arms - Almace"', '『焰圣剑－阿尔梅斯』', '『焔聖剣－アルマス』', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡装备中的场合才能发动。从自己的卡组·墓地选「『焰圣剑-阿尔玛斯』」以外的1张「焰圣剑」装备魔法卡给可以把那张卡装备的自己场上1只怪兽装备。那之后，这张卡破坏。 ②：装备怪兽被送去墓地让这张卡被送去墓地的场合，以自己的墓地·除外状态的1只战士族·炎属性怪兽为对象才能发动。那只怪兽加入手卡。'),
(37478723, '"Infernoble Arms - Durendal"', '『焰圣剑－杜兰德尔』', '『焔聖剣－デュランダル』', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡装备中的场合才能发动。从卡组把1只5星以下的战士族·炎属性怪兽加入手卡。那之后，这张卡破坏。 ②：装备怪兽被送去墓地让这张卡被送去墓地的场合，以自己墓地1只5星以下的战士族·炎属性怪兽为对象才能发动。那只怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是战士族怪兽不能特殊召唤。'),
(64867422, '"Infernoble Arms - Hauteclere"', '『焰圣剑－奥特克莱尔』', '『焔聖剣－オートクレール』', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡装备中的场合，以自己场上1只表侧表示怪兽为对象才能发动。这个回合，自己不用那只怪兽不能攻击宣言，那只怪兽在同1次的战斗阶段中可以作2次攻击。那之后，这张卡破坏。 ②：装备怪兽被送去墓地让这张卡被送去墓地的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽破坏。'),
(90861137, '"Infernoble Arms - Joyeuse"', '『焰圣剑－咎瓦尤斯』', '『焔聖剣－ジョワユーズ』', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡装备中的场合，以自己墓地1只战士族·炎属性怪兽为对象才能发动。那只怪兽加入手卡。那之后，这张卡破坏。 ②：装备怪兽被送去墓地让这张卡被送去墓地的场合才能发动。从手卡把1只战士族·炎属性怪兽特殊召唤。'),
(44256816, '1st Movement Solo', '独奏第１乐章', '独奏の第１楽章', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「独奏的第1乐章」在1回合只能发动1张，这张卡发动的回合，自己不是「幻奏」怪兽不能特殊召唤。 ①：自己场上没有怪兽存在的场合才能发动。从手卡·卡组把1只4星以下的「幻奏」怪兽特殊召唤。'),
(86988864, '3-Hump Lacooda', '三峰驼', 'みつこぶラクーダ', 'Effect Monster', 'Beast', 'EARTH', 3, 500, 1500, '当自己场上存在3只表侧表示的「三峰驼」时，祭掉其中2只，就可以抽3张卡。'),
(11714098, '30,000-Year White Turtle', '3万年的白龟', '３万年の白亀', 'Normal Monster', 'Aqua', 'WATER', 5, 1250, 2100, '生活了三万年的巨大乌龟。守备力高。'),
(83994646, '4-Starred Ladybug of Doom', '死之四星瓢虫', '死の４つ星てんとう虫', 'Flip Effect Monster', 'Insect', 'WIND', 3, 800, 1200, '反转：对方场上表侧表示存在的4星怪兽全部破坏。'),
(67048711, '7', '7', '7', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '当自己场上凑齐3张以表侧表示存在的「7」时，自己抽3张卡。之后，所有的「7」被破坏。当这张卡从场上被送去墓地时，自己回复700基本分。'),
(23771716, '7 Colored Fish', '彩虹鱼', 'レインボー・フィッシュ', 'Normal Monster', 'Fish', 'WATER', 4, 1800, 800, '非常珍奇的七色鱼，要捕捉它非常困难。'),
(86198326, '7 Completed', '7卡', '７カード', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '机械族怪兽才能装备。装备怪兽的攻击力或者守备力上升700。'),
(14261867, '8-Claws Scorpion', '八钳蝎', '八つ手サソリ', 'Effect Monster', 'Insect', 'DARK', 2, 300, 200, '这张卡1个回合可以有1次变回里侧守备表示。这张卡攻击对方的里侧守备表示的怪兽的场合，这张卡在伤害计算时攻击力以2400计算。'),
(4731783, 'A Bao A Qu, the Lightless Shadow', '无光之影 阿宝阿库', '光なき影 ア＝バオ・ア・クゥー', 'Link Monster', 'Fiend', 'DARK', NULL, 2800, NULL, '包含恶魔族怪兽的怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，可以丢弃1张手卡，从以下效果选择1个发动。 ●场上1张卡破坏。 ●这张卡直到结束阶段除外，从自己墓地把1只光·暗属性怪兽特殊召唤。 ②：自己准备阶段才能发动。自己抽出自己墓地的怪兽的种族种类的数量。那之后，选抽出数量的自己手卡用喜欢的顺序回到卡组下面。'),
(24140059, 'A Cat of Ill Omen', '告知不幸的黑猫', '不幸を告げる黒猫', 'Flip Effect Monster', 'Beast', 'DARK', 2, 500, 300, '①：这张卡反转的场合发动。从卡组选1张陷阱卡在卡组最上面放置。「王家长眠之谷」在场上存在的场合，那张陷阱卡可以作为在卡组最上面放置的代替而加入手卡。'),
(6850209, 'A Deal with Dark Ruler', '与恶魔的暗中交易', 'デーモンとの駆け引き', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这张卡只能在有8星以上的怪兽从自己场上被送去墓地的回合发动。从自己的手卡或卡组特殊召唤「狂暴死龙」上场。'),
(49140998, 'A Feather of the Phoenix', '凤凰神的羽毛', '鳳凰神の羽根', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '丢弃1张手卡，选择自己墓地1张卡才能发动。选择的卡回到卡组最上面。'),
(68170903, 'A Feint Plan', '佯动作战', '陽動作戦', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个回合，双方不能向里侧表示怪兽攻击。'),
(21597117, 'A Hero Emerges', '英雄拜访', 'ヒーロー見参', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时才能发动。自己1张手卡由对方随机选。那是怪兽的场合，在自己场上特殊召唤，不是的场合送去墓地。'),
(8949584, 'A Hero Lives', '英雄到来', 'ヒーローアライブ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上没有表侧表示怪兽存在的场合，把基本分支付一半才能发动。从卡组把1只4星以下的「元素英雄」怪兽特殊召唤。'),
(295517, 'A Legendary Ocean', '传说之都 亚特兰蒂斯', '伝説の都 アトランティス', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名在规则上当作「海」使用。 ①：场上的水属性怪兽的攻击力·守备力上升200。 ②：只要这张卡在场地区域存在，双方的手卡·场上的水属性怪兽的等级下降1星。'),
(32207100, 'A Major Upset', '大爆冷门', '大番狂わせ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上表侧攻击表示存在的1只2星以下的怪兽解放发动。场上表侧表示存在的7星以上的特殊召唤的怪兽全部回到持有者手卡。'),
(51351302, 'A Man with Wdjat', '有法眼的男人', 'ウジャト眼を持つ男', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1600, 1600, '这张卡通常召唤时和每到自己准备阶段时，选择对方场上1张盖放的卡，确认后回复原状。'),
(5728014, 'A Rival Appears!', '对手登场！', 'ライバル登場！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择对方场上表侧表示存在的1只怪兽。从手卡特殊召唤1只和选择怪兽等级一样的怪兽。'),
(44553392, 'A Shattered, Colorless Realm', '识无边世坏', '識無辺世壊', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上有「维舍斯-阿修特罗德」存在的场合，以场上1张卡为对象才能发动。那张卡破坏。那之后，破坏的卡的原本卡名是「维舍斯-阿修特罗德」的场合，可以选除外的1只自己的「维萨斯-斯塔弗罗斯特」特殊召唤。「维舍斯-阿修特罗德」以外的场合，可以选自己场上1只「维舍斯-阿修特罗德」，那个攻击力上升1500。'),
(23587624, 'A Wild Monster Appears!', '青天霹雳', '青天の霹靂', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方场上有怪兽存在，自己场上没有怪兽存在的场合才能发动。把1只原本等级是10星以下的不能通常召唤的怪兽无视召唤条件从手卡特殊召唤。这个效果特殊召唤的怪兽不受那只怪兽以外的自己的卡的效果影响，下次的对方结束阶段回到持有者卡组。这个回合，自己不能把怪兽通常召唤·特殊召唤，对方受到的全部伤害变成0。'),
(28596933, 'A Wingbeat of Giant Dragon', '巨龙振翅', '巨竜の羽ばたき', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：选自己场上1只5星以上的龙族怪兽回到持有者手卡，场上的魔法·陷阱卡全部破坏。'),
(30012506, 'A-Assault Core', 'A－强袭核心', 'A－アサルト・コア', 'Union Effect Monster', 'Machine', 'LIGHT', 4, 1900, 200, '①：1回合1次，可以把1个以下效果发动。 ●以自己场上1只机械族·光属性怪兽为对象，把这张卡当作装备魔法卡使用来装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备状态的这张卡特殊召唤。 ②：装备怪兽不受其他的对方怪兽的效果影响。 ③：这张卡从场上送去墓地的场合才能发动。自己墓地1只其他的同盟怪兽加入手卡。'),
(13026402, 'A-Team: Trap Disposal Unit', '陷阱处理班 A组', 'トラップ処理班 Aチーム', 'Effect Monster', 'Machine', 'FIRE', 2, 300, 400, '这个效果可以在对方回合使用。对方发动陷阱时，可以把表侧表示的这张卡作祭品，陷阱的发动无效并且破坏。'),
(75926389, 'A-to-Z Energy Load', 'AtoZ 能量加载', 'AtoZエナジーロード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方把魔法·陷阱·怪兽的效果发动时才能发动。自己抽出自己场上的8星以上而机械族·光属性的融合怪兽的数量。 ②：自己准备阶段，把墓地的这张卡除外才能发动。包含同盟怪兽的自己的除外状态的最多6只机械族·光属性怪兽回到卡组。'),
(65172015, 'A-to-Z-Dragon Buster Cannon', 'AtoZ－龙型爆裂加农炮', 'AtoZ－ドラゴン・バスターキャノン', 'Fusion Monster', 'Machine', 'LIGHT', 10, 4000, 4000, '「ABC-神龙歼灭者」＋「XYZ-神龙炮」 把自己场上的原本卡名是上记的卡除外的场合才能特殊召唤。 ①：对方把怪兽的效果·魔法·陷阱卡发动时，丢弃1张手卡才能发动。那个发动无效并破坏。 ②：自己·对方回合，把场上的这张卡除外，以自己的除外状态的「ABC-神龙歼灭者」「XYZ-神龙炮」各1只为对象才能发动。那些怪兽特殊召唤。'),
(28645123, 'A.I. Challenge You', '决战-艾-', '果たし－Ai－', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：对方场上的怪兽的攻击力下降自己场上的卡数量×100。 ②：自己的「@火灵天星」怪兽进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。 ③：自己的「@火灵天星」怪兽被战斗破坏时，以那怪兽以外的自己墓地1只攻击力2300的电子界族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(79015062, 'A.I. Connect', '-艾-互联互接', '繋がり－Ai－', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把手卡1只电子界族怪兽给对方观看才能发动。给人观看的怪兽属性的以下效果适用。这张卡的发动后，直到回合结束时自己不是电子界族怪兽不能特殊召唤。 ●暗：给人观看的怪兽特殊召唤，从卡组把1只暗属性以外而4星以下的电子界族怪兽加入手卡。 ●暗以外：给人观看的怪兽回到卡组，和回去的怪兽属性不同的1只「@火灵天星」怪兽从卡组加入手卡。'),
(10493654, 'A.I. Contact', '-艾-眼神交流', 'Ai－コンタクト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己的场地区域有「火灵天星“艾”心乐园岛」存在的场合，把手卡1张「火灵天星“艾”心乐园岛」给对方观看才能发动。给人观看的卡回到卡组最下面，自己从卡组抽3张。'),
(59332125, 'A.I. Love Fusion', '-艾-我爱融合', 'Aiラブ融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·场上把电子界族融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。把自己的「@火灵天星」怪兽作为融合素材的场合，对方场上的连接怪兽也能有最多1只作为融合素材。'),
(6552971, 'A.I. Meet You', '邂逅-艾-', 'めぐり－Ai－', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把手卡·额外卡组1只攻击力2300的电子界族怪兽给对方观看，把持有和那只怪兽相同属性的1只「@火灵天星」怪兽从卡组加入手卡。发动后，这个回合中自己对这个效果给人观看的怪兽或者那些同名怪兽的特殊召唤没有成功的场合，结束阶段让自己受到2300伤害。这张卡的发动后，直到回合结束时自己不能把电子界族以外的怪兽的效果发动。'),
(77421977, 'A.I. Shadow', '-艾-眼影', 'Aiシャドー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。以自己场上1只「@火灵天星」怪兽为对象才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，作为对象的怪兽的攻击力上升800，可以攻击的对方怪兽必须向作为对象的怪兽作出攻击。 ②：魔法与陷阱区域的表侧表示的这张卡因对方的效果从场上离开，被送去墓地的场合或者被除外的场合发动。自己从卡组抽1张。'),
(85327820, 'A.I.''s Ritual', '-艾-爱之仪式', 'Aiの儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '电子界族仪式怪兽的降临必需。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的「@火灵天星」怪兽解放，从手卡把1只电子界族仪式怪兽仪式召唤。发动时自己场上有「@火灵天星」怪兽存在的场合，自己墓地的「@火灵天星」怪兽也能作为解放的代替而除外。'),
(54374642, 'A.I.''s Show', '-艾-契合演出', 'Ai－SHOW', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：额外怪兽区域有自己的连接3以上的「@火灵天星」怪兽存在的场合，对方怪兽的攻击宣言时才能发动。攻击力合计最多到那只攻击怪兽的攻击力以下为止，选连接怪兽以外的攻击力2300的电子界族怪兽任意数量从额外卡组特殊召唤。那之后，战斗阶段结束。'),
(22933016, 'A.I.dle Reborn', '-艾-待机重生', 'Aiドリング・ボーン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只「@火灵天星」怪兽为对象才能发动。那只怪兽特殊召唤。这张卡的发动后，直到回合结束时自己不是电子界族怪兽不能特殊召唤。 ②：怪兽之间进行战斗的攻击宣言时，把墓地的这张卡和1张手卡除外，从自己墓地的卡以及除外的自己的卡之中以「“艾”闲者苏生」以外的1张「“艾”」魔法·陷阱卡为对象才能发动。那张卡加入手卡。'),
(69381150, 'A.I.Q', '-艾-IQ', 'Ai－Q', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上有「@火灵天星」怪兽存在的场合才能把这张卡发动。这张卡的控制者在每次自己准备阶段把自己场上1只连接怪兽解放。或者不解放让这张卡破坏。 ①：只要这张卡在魔法与陷阱区域存在，那个期间双方1回合只能有1次连接召唤。'),
(96146814, 'A/D Changer', 'AD变更者', 'ADチェンジャー', 'Effect Monster', 'Warrior', 'LIGHT', 1, 100, 100, '把墓地存在的这张卡从游戏中除外，选择场上存在的1只怪兽发动。选择的怪兽的表示形式变更。'),
(12694768, 'Abaki', '暴鬼', '暴鬼', 'Effect Monster', 'Fiend', 'FIRE', 4, 1700, 1100, '这张卡被战斗破坏送去墓地时，双方受到500分伤害。'),
(89718302, 'Abare Ushioni', '暴走牛鬼', '暴れ牛鬼', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1200, 1200, '猜硬币正反。 ●猜中的场合：给与对方基本分1000分的伤害。 ●猜错的场合：自己基本分受到1000分的伤害。这个效果1回合只能1次，在自己回合的主要阶段使用。'),
(1561110, 'ABC-Dragon Buster', 'ABC－龙型爆裂炮', 'ABC－ドラゴン・バスター', 'Fusion Monster', 'Machine', 'LIGHT', 8, 3000, 2800, '「A-突击核」＋「B-破坏龙兽」＋「C-粉碎翼龙」 把自己的场上·墓地的上记的卡除外的场合才能从额外卡组特殊召唤。 ①：自己·对方回合1次，丢弃1张手卡，以场上1张卡为对象才能发动。那张卡除外。 ②：对方回合，把这张卡解放，以自己的除外状态的3只机械族·光属性同盟怪兽为对象才能发动（同名卡最多1张）。那些怪兽特殊召唤。'),
(21846145, 'Abduction', '绑架', 'アブダクション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方场上1只表侧表示怪兽为对象才能发动。原本种族、原本属性和原本的等级·阶级·连接是和作为对象的怪兽相同的1只怪兽从卡组·额外卡组除外，得到作为对象的怪兽的控制权。把原本卡名和作为对象的怪兽相同的怪兽用这个效果除外的场合，这个效果得到控制权的怪兽的效果无效化。'),
(80801743, 'Abominable Chamber of the Unchained', '破械双极', '破械雙極', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·墓地选1只「破械」怪兽特殊召唤。 ②：盖放的这张卡被效果破坏的场合才能发动。从卡组把1只「破械」怪兽特殊召唤。'),
(1966438, 'Abominable Unchained Soul', '双极破械神', '雙極の破械神', 'Effect Monster', 'Fiend', 'DARK', 8, 3000, 1500, '自己对「双极之破械神」1回合只能有1次特殊召唤。 ①：自己场上的卡被战斗·效果破坏的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤的场合，丢弃1张手卡才能发动。场上1张卡破坏。 ③：场上的这张卡被破坏送去墓地的回合的结束阶段才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合回到卡组最下面。'),
(27412542, 'Abomination''s Prison', '双王之械', '雙王の械', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1张「破械」卡加入手卡。 ②：盖放的这张卡被效果破坏的场合才能发动。从卡组把1只「破械」怪兽特殊召唤。'),
(80073414, 'Absolute Axon Kicker', '绝对超能者', 'アブソリュートサイキッカー', 'Fusion Monster', 'Psychic', 'LIGHT', 11, 3400, 2200, '念动力族同调怪兽＋同调怪兽 这张卡用融合召唤才能从额外卡组特殊召唤。这个卡名的③的效果1回合只能使用1次。 ①：这张卡融合召唤的场合，支付2000基本分才能发动。对方场上的表侧表示卡全部除外。 ②：这张卡只要在怪兽区域存在，不会被效果破坏。 ③：把这个回合没有送去墓地的这张卡从墓地除外才能发动。从额外卡组把1只念动力族·10星融合怪兽当作融合召唤作特殊召唤。'),
(70832512, 'Absolute Crusader', '真十字军', 'レアル・クルセイダー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 1200, '5星以上的怪兽特殊召唤成功时，必须把场上表侧表示存在的这张卡解放发动。那些5星以上的怪兽破坏。'),
(27744077, 'Absolute End', '绝体绝命', '絶体絶命', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '只能在对方回合发动。这个回合对方怪兽的攻击，全部变成对玩家的直接攻击。'),
(27553701, 'Absolute King - Megaplunder', '绝对的王者-大盗掠龙', '絶対なる王者－メガプランダー', 'Normal Monster', 'Dinosaur', 'EARTH', 6, 2000, 1500, '统治大地的恐龙之王。会用强有力的吼叫来震慑敌人哦！'),
(60990740, 'Absolute King Back Jack', '绝对王 背包杰克', '絶対王 バック・ジャック', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方回合把墓地的这张卡除外才能发动。自己卡组最上面的卡翻开，那张卡是通常陷阱卡的场合，在自己场上盖放。不是的场合，那张卡送去墓地。这个效果盖放的卡在盖放的回合也能发动。 ②：这张卡被送去墓地的场合才能发动。从自己卡组上面把3张卡确认，用喜欢的顺序回到卡组上面。'),
(51779204, 'Absolute Powerforce', '绝对力量威压', 'アブソリュート・パワーフォース', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己场上1只「红莲魔龙」为对象才能发动。这个回合，那只自己怪兽和对方怪兽进行战斗的场合，直到伤害步骤结束时以下效果适用。 ●作为对象的怪兽的攻击力上升1000。 ●对方不能把魔法·陷阱·怪兽的效果发动。 ●作为对象的怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ●那次战斗发生的对对方的战斗伤害变成2倍。'),
(71422989, 'Absorb Fusion', '吸光结合', '吸光融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是「宝石骑士」怪兽不能特殊召唤。 ①：从卡组把1张「宝石骑士」卡加入手卡。那之后，以下效果可以适用。 ●自己的手卡·场上的怪兽作为融合素材除外，把1只「宝石骑士」融合怪兽融合召唤。'),
(3900605, 'Absorbing Jar', '吸收壶', 'アブソーブポッド', 'Flip Effect Monster', 'Rock', 'EARTH', 3, 600, 500, '反转∶场上盖放的魔法·陷阱卡全部破坏。破坏的卡的控制者从卡组抽出破坏数量的卡。这个回合，自己不能把卡盖放。'),
(49771608, 'Absorbing Kid from the Sky', '吸收天儿', '吸収天児', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1300, 1000, '这张卡战斗破坏怪兽并将其送去墓地时，自己回复被破坏的怪兽等级×300基本分。'),
(67748760, 'Absorouter Dragon', '绝对路由龙', 'アブソルーター・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 7, 1200, 2800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有「弹丸」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡被送去墓地的场合才能发动。从卡组把1只「弹丸」怪兽加入手卡。'),
(15308295, 'Abyss Actor - Comic Relief', '魔界剧团－谐趣龙套', '魔界劇団－コミック・リリーフ', 'Pendulum Effect Monster', 'Fiend', 'DARK', 3, 1000, 2000, '①：这张卡的战斗发生的对自己的战斗伤害变成0。 ②：自己准备阶段发动。这张卡的控制权移给对方。 ③：1回合1次，这张卡的控制权转移的场合发动。这张卡的原本持有者可以选自身的魔法与陷阱区域盖放的1张「魔界台本」魔法卡破坏。'),
(44179224, 'Abyss Actor - Curtain Raiser', '魔界剧团－启幕人', '魔界劇団カーテン・ライザー', 'Pendulum Effect Monster', 'Fiend', 'DARK', 4, 1100, 1000, '①：自己场上没有这张卡以外的怪兽存在的场合，这张卡的攻击力上升1100。 ②：1回合1次，从卡组把1张「魔界台本」魔法卡送去墓地才能发动。从自己的额外卡组把1只表侧表示的「魔界剧团」灵摆怪兽加入手卡。'),
(52240819, 'Abyss Actor - Evil Heel', '魔界剧团－魔鬼反派', '魔界劇団－デビル・ヒール', 'Pendulum Effect Monster', 'Fiend', 'DARK', 8, 3000, 2000, '①：这张卡召唤·特殊召唤成功的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时下降自己场上的「魔界剧团」怪兽数量×1000。 ②：这张卡战斗破坏对方怪兽时，以自己墓地1张「魔界台本」魔法卡为对象才能发动。那张卡在自己场上盖放。'),
(88412339, 'Abyss Actor - Extras', '魔界剧团－群演', '魔界劇団－エキストラ', 'Pendulum Effect Monster', 'Fiend', 'DARK', 1, 100, 100, '这个卡名的怪兽效果1回合只能使用1次。 ①：把这张卡解放才能发动。从卡组选1只「魔界剧团」灵摆怪兽在自己的灵摆区域放置。这个效果的发动后，直到回合结束时自己不是「魔界剧团」怪兽不能特殊召唤，不能把「魔界剧团-临时演员」的灵摆效果发动。'),
(99634927, 'Abyss Actor - Funky Comedian', '魔界剧团－时髦谐星', '魔界劇団－ファンキー・コメディアン', 'Pendulum Effect Monster', 'Fiend', 'DARK', 1, 300, 200, '「魔界剧团-时髦笑星」的②的怪兽效果1回合只能使用1次，这个效果发动的回合，这张卡不能攻击。 ①：这张卡召唤·特殊召唤成功的场合才能发动。这张卡的攻击力直到回合结束时上升自己场上的「魔界剧团」怪兽数量×300。 ②：以这张卡以外的自己场上1只「魔界剧团」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升这张卡的攻击力数值。'),
(2368215, 'Abyss Actor - Hyper Director', '魔界剧团－超群导演', '魔界劇団－ハイパー・ディレクター', 'Link Monster', 'Fiend', 'DARK', NULL, 800, NULL, '「魔界剧团」灵摆怪兽1只 这个卡名的效果1回合只能使用1次。 ①：以自己的灵摆区域1张卡为对象才能发动。那张卡特殊召唤。那之后，从卡组的怪兽以及自己的额外卡组的表侧表示的灵摆怪兽之中选和特殊召唤的怪兽卡名不同的1只「魔界剧团」灵摆怪兽在自己的灵摆区域放置。这个效果的发动后，直到回合结束时自己不是「魔界剧团」怪兽不能召唤·特殊召唤。'),
(24907044, 'Abyss Actor - Leading Lady', '魔界剧团－美丽女主演', '魔界劇団－プリティ・ヒロイン', 'Pendulum Effect Monster', 'Fiend', 'DARK', 4, 1500, 1000, '①：1回合1次，自己或者对方受到战斗伤害时，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力下降那次战斗伤害的数值。 ②：怪兽区域的这张卡被战斗或者对方的效果破坏时才能发动。从卡组选1张「魔界台本」魔法卡在自己场上盖放。'),
(65477143, 'Abyss Actor - Liberty Dramatist', '魔界剧团－自由剧作家', '魔界劇団－リバティ・ドラマチスト', 'Pendulum Effect Monster', 'Fiend', 'DARK', 4, 1500, 1500, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：这张卡从灵摆区域的特殊召唤成功的场合发动。这张卡的原本持有者从自身卡组把3张「魔界台本」魔法卡给对方观看，对方从那之中随机选1张。那1张卡在自身场上盖放，剩下的卡回到卡组。这个效果盖放的卡在结束阶段破坏。 ②：这张卡被破坏的场合才能发动。从自己墓地选1张「魔界台本」魔法卡回到卡组。'),
(78310590, 'Abyss Actor - Mellow Madonna', '魔界剧团－成熟女演员', '魔界劇団－メロー・マドンナ', 'Pendulum Effect Monster', 'Fiend', 'DARK', 7, 1800, 2500, '这个卡名的①③的怪兽效果1回合各能使用1次。 ①：自己的灵摆怪兽被战斗破坏时才能发动。这张卡从手卡特殊召唤。 ②：这张卡的攻击力上升自己墓地的「魔界台本」魔法卡数量×100。 ③：「魔界台本」魔法卡的效果发动的场合才能发动。从卡组把1只4星以下的「魔界剧团」灵摆怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到持有者手卡。'),
(51028231, 'Abyss Actor - Sassy Rookie', '魔界剧团－莽撞新人', '魔界劇団－サッシー・ルーキー', 'Pendulum Effect Monster', 'Fiend', 'DARK', 4, 1700, 1000, '①：这张卡1回合只有1次不会被战斗·效果破坏。 ②：怪兽区域的这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把「魔界剧团-莽撞新人」以外的1只4星以下的「魔界剧团」怪兽特殊召唤。 ③：这张卡在灵摆区域被破坏的场合，以对方场上1只4星以下的怪兽为对象才能发动。那只怪兽破坏。'),
(47404795, 'Abyss Actor - Super Producer', '魔界剧团－超级制作人', '魔界劇団－スーパー・プロデューサー', 'Link Monster', 'Fiend', 'DARK', NULL, 1600, NULL, '包含恶魔族怪兽的怪兽2只 这个卡名的效果1回合只能使用1次。 ①：自己·对方的主要阶段，以自己场上1张表侧表示的卡为对象才能发动。那张卡破坏。那之后，可以从以下效果选1个适用。 ●从卡组选1张「魔界剧场「奇幻剧场」」在自己的场地区域表侧表示放置。 ●从卡组选1只「魔界剧团」灵摆怪兽在自己的灵摆区域放置。'),
(25629622, 'Abyss Actor - Superstar', '魔界剧团－巨星', '魔界劇団－ビッグ・スター', 'Pendulum Effect Monster', 'Fiend', 'DARK', 7, 2500, 1800, '①：在这张卡的召唤·特殊召唤成功时对方不能把魔法·陷阱卡的效果发动。 ②：1回合1次，自己主要阶段才能发动。从卡组选1张「魔界台本」魔法卡在自己场上盖放。这个效果盖放的卡在结束阶段送去墓地。'),
(39024589, 'Abyss Actor - Trendy Understudy', '魔界剧团－潮人配角', '魔界劇団－ダンディ・バイプレイヤー', 'Pendulum Effect Monster', 'Fiend', 'DARK', 2, 700, 700, '这个卡名的怪兽效果1回合只能使用1次。 ①：自己的灵摆区域有2张「魔界剧团」卡存在的场合，把这张卡解放才能发动。从手卡以及自己的额外卡组的表侧表示怪兽之中把1只1星或者8星的「魔界剧团」灵摆怪兽特殊召唤。'),
(7279373, 'Abyss Actor - Twinkle Little Star', '魔界剧团－闪烁小明星', '魔界劇団－ティンクル・リトルスター', 'Pendulum Effect Monster', 'Fiend', 'DARK', 4, 1000, 1000, '①：这张卡在自己回合不会被战斗破坏，同1次的战斗阶段中最多3次可以向怪兽攻击。'),
(51391183, 'Abyss Actor - Wild Hope', '魔界剧团－狂野新星', '魔界劇団－ワイルド・ホープ', 'Pendulum Effect Monster', 'Fiend', 'DARK', 4, 1600, 1200, '这个卡名的②的怪兽效果1回合只能使用1次。 ①：1回合1次，自己主要阶段才能发动。这张卡的攻击力直到回合结束时上升自己场上的「魔界剧团」怪兽种类×100。 ②：这张卡被战斗·效果破坏的场合才能发动。从卡组把「魔界剧团-狂放新秀」以外的1张「魔界剧团」卡加入手卡。'),
(59057953, 'Abyss Actors Back Stage', '魔界剧团之进入休息室', '魔界劇団の楽屋入り', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己的灵摆区域有2张「魔界剧团」卡存在的场合才能发动。从卡组选2只「魔界剧团」灵摆怪兽表侧表示加入自己的额外卡组（同名卡最多1张）。'),
(4682617, 'Abyss Actors'' Curtain Call', '魔界剧团之谢幕', '魔界劇団のカーテンコール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：「魔界台本」魔法卡的效果发动的回合才能发动。把最多有自己墓地的「魔界台本」魔法卡数量的表侧表示的「魔界剧团」灵摆怪兽从自己的额外卡组加入手卡。那之后，可以把最多有这个效果加入手卡的怪兽数量的「魔界剧团」灵摆怪兽从手卡特殊召唤（同名卡最多1张）。这张卡的发动后，直到回合结束时自己不是「魔界剧团」灵摆怪兽不能特殊召唤。'),
(6004133, 'Abyss Actors'' Dress Rehearsal', '魔界剧团之总彩排', '魔界劇団のゲネプロ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己主要阶段1开始时才能发动。从卡组把1张「魔界剧团」卡和1张「魔界台本」魔法卡加入手卡。这张卡的发动后，直到回合结束时自己不是「魔界剧团」怪兽不能灵摆召唤。'),
(21044178, 'Abyss Dweller', '深渊潜伏者', '深淵に潜む者', 'XYZ Monster', 'Sea Serpent', 'WATER', 4, 1700, 1400, '4星怪兽×2 ①：这张卡有水属性怪兽在作为超量素材的场合，自己场上的水属性怪兽的攻击力上升500。 ②：自己·对方回合1次，把这张卡1个超量素材取除才能发动。这个回合，对方不能把墓地的卡的效果发动。'),
(40387124, 'Abyss Flower', '开在深渊的花', '深淵に咲く花', 'Normal Monster', 'Plant', 'EARTH', 2, 750, 400, '默默生长在黑暗的深渊里的花，平常很难见到。'),
(82184400, 'Abyss Keeper', '邃渊卫士', 'アビス・オーパー', 'Link Monster', 'Fish', 'WATER', NULL, 1500, NULL, '水属性怪兽2只 这个卡名的①②的效果1回合各能使用1次。这张卡在连接召唤的回合不能作为连接素材。 ①：这张卡连接召唤成功的场合才能发动。从手卡把1只鱼族怪兽在作为这张卡所连接区的自己场上特殊召唤。 ②：以这张卡以外的自己场上1只鱼族怪兽和对方场上1张卡为对象才能发动。那些卡除外。'),
(77297908, 'Abyss Playhouse - Fantastic Theater', '魔界剧场“幻想剧院”', '魔界劇場「ファンタスティックシアター」', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡1只「魔界剧团」灵摆怪兽和1张「魔界台本」魔法卡给对方观看才能发动。和给人观看的魔法卡卡名不同的1张「魔界台本」魔法卡从卡组加入手卡。 ②：只要灵摆召唤的「魔界剧团」灵摆怪兽在自己场上存在，对方发动的怪兽的效果变成「选对方场上盖放的1张魔法·陷阱卡破坏」。'),
(86578200, 'Abyss Prop - Wild Wagon', '魔界大道具“逃跑马车”', '魔界大道具「ニゲ馬車」', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己的「魔界剧团」怪兽在1回合各有1次不会被战斗破坏。 ②：1回合1次，以自己场上1只「魔界剧团」怪兽为对象才能发动。直到对方回合结束时，对方不能把那只怪兽作为效果的对象。 ③：自己的额外卡组有表侧表示的「魔界剧团」灵摆怪兽存在，盖放的这张卡被对方的效果破坏的场合才能发动。对方场上的卡全部回到持有者手卡。'),
(70564929, 'Abyss Script - Abysstainment', '魔界剧本“魔界的宴娱”', '魔界台本「魔界の宴咜女」', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合可以使用最多2次。 ①：把自己场上1只「魔界剧团」怪兽解放，以自己墓地1张「魔界台本」魔法卡为对象才能发动。那张卡在自己场上盖放。 ②：自己的额外卡组有表侧表示的「魔界剧团」灵摆怪兽存在，盖放的这张卡被对方的效果破坏的场合才能发动。从卡组把「魔界剧团」灵摆怪兽任意数量特殊召唤。'),
(33503878, 'Abyss Script - Dramatic Story', '魔界剧本“戏剧性故事”', '魔界台本「ドラマチック・ストーリー」', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「魔界剧团」灵摆怪兽为对象才能发动。和那只怪兽卡名不同的1只「魔界剧团」怪兽从卡组特殊召唤。那之后，作为对象的怪兽在自己的灵摆区域放置或破坏。 ②：自己的额外卡组有表侧表示的「魔界剧团」灵摆怪兽存在，盖放的这张卡被对方的效果破坏的场合才能发动。选场上最多2张卡回到持有者手卡。'),
(87390798, 'Abyss Script - Fantasy Magic', '魔界剧本“幻想魔法”', '魔界台本「ファンタジー・マジック」', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「魔界剧团」怪兽为对象才能发动。这个回合，没被和那只怪兽的战斗破坏的怪兽在伤害步骤结束时回到持有者手卡。 ②：自己的额外卡组有表侧表示的「魔界剧团」灵摆怪兽存在，盖放的这张卡被对方的效果破坏的场合，以对方场上1张卡为对象才能发动。那张卡回到持有者卡组最上面。'),
(50179591, 'Abyss Script - Fire Dragon''s Lair', '魔界剧本“火龙的住处”', '魔界台本「火竜の住処」', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「魔界台本「火龙的住处」」的②的效果1回合只能使用1次。 ①：以自己场上1只「魔界剧团」怪兽为对象才能发动。这个回合，那只怪兽战斗破坏对方怪兽的场合，对方从额外卡组选3只怪兽除外。 ②：自己的额外卡组有表侧表示的「魔界剧团」灵摆怪兽存在，盖放的这张卡被对方的效果破坏的场合才能发动。把对方的额外卡组确认，选那之内的1张除外。'),
(23784496, 'Abyss Script - Opening Ceremony', '魔界剧本“开幕式”', '魔界台本「オープニング・セレモニー」', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己回复自己场上的「魔界剧团」怪兽数量×500基本分。 ②：自己的额外卡组有表侧表示的「魔界剧团」灵摆怪兽存在，盖放的这张卡被对方的效果破坏的场合才能发动。自己直到手卡变成5张为止从卡组抽卡。'),
(13662809, 'Abyss Script - Rise of the Abyss King', '魔界剧本“魔王降临”', '魔界台本「魔王の降臨」', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以最多有自己场上的攻击表示的「魔界剧团」怪兽种类数量的场上的表侧表示的卡为对象才能发动。那些卡破坏。自己场上有7星以上的「魔界剧团」怪兽存在的场合，对方不能对应这张卡的发动把效果发动。 ②：自己的额外卡组有表侧表示的「魔界剧团」灵摆怪兽存在，盖放的这张卡被对方的效果破坏的场合才能发动。从卡组把「魔界剧团」卡或者「魔界台本」魔法卡合计最多2张加入手卡（同名卡最多1张）。'),
(41803903, 'Abyss Script - Romantic Terror', '魔界剧本“浪漫语者”', '魔界台本「ロマンティック・テラー」', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：选自己场上1只「魔界剧团」灵摆怪兽回到持有者手卡，原本卡名和回到手卡的怪兽不同的1只表侧表示的「魔界剧团」灵摆怪兽从自己的额外卡组守备表示特殊召唤。 ②：自己的额外卡组有表侧表示的「魔界剧团」灵摆怪兽存在，盖放的这张卡被对方的效果破坏的场合才能发动。从卡组选「魔界台本」魔法卡任意数量在自己的魔法与陷阱区域盖放。'),
(61496006, 'Abyss Shark', '邃渊鲨', 'アビス・シャーク', 'Effect Monster', 'Fish', 'WATER', 5, 1200, 700, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上的怪兽只有水属性怪兽的场合才能发动。这张卡从手卡特殊召唤，从卡组把「渊鲨」以外的1只3～5星的鱼族怪兽加入手卡。这个回合，自己不是水属性怪兽不能特殊召唤，自己的「No.」怪兽用和怪兽的战斗给与对方的战斗伤害只有1次变成2倍。 ②：把这张卡在「No.」怪兽的超量召唤使用的场合，可以把这张卡的等级当作3星或4星使用。'),
(18318842, 'Abyss Soldier', '深渊士兵', 'アビス・ソルジャー', 'Effect Monster', 'Aqua', 'WATER', 4, 1800, 1300, '①：1回合1次，从手卡把1只水属性怪兽丢弃去墓地，以场上1张卡为对象才能发动。那张卡回到持有者手卡。'),
(97232518, 'Abyss Stungray', '深渊的电击魟', '深淵のスタングレイ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡发动后变成效果怪兽（雷族·光·5星·攻1900/守0）在怪兽区域特殊召唤。这张卡也当作陷阱卡使用。 ②：这张卡的效果特殊召唤的这张卡不会被战斗破坏。'),
(88409165, 'Abyss Warrior', '深渊战士', 'アビス・ウォリアー', 'Effect Monster', 'Aqua', 'WATER', 4, 1800, 1300, '1回合1次，从手卡把1只水属性怪兽丢弃去墓地，选择自己或者对方的墓地1只怪兽才能发动。选择的怪兽回到持有者卡组最上面或者最下面。'),
(19596712, 'Abyss-scale of Cetus', '邃渊鳞甲－塞特斯', 'アビスケイル－ケートス', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「水精鳞」的怪兽才能装备。装备怪兽的攻击力上升800。只要这张卡在场上存在，对方场上发动的陷阱卡的效果无效。那之后，这张卡送去墓地。'),
(8719957, 'Abyss-scale of the Kraken', '邃渊鳞甲－克拉肯', 'アビスケイル－クラーケン', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「水精鳞」的怪兽才能装备。装备怪兽的攻击力上升400。只要这张卡在场上存在，对方场上发动的效果怪兽的效果无效。那之后，这张卡送去墓地。'),
(72932673, 'Abyss-scale of the Mizuchi', '邃渊鳞甲－蛟', 'アビスケイル－ミヅチ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「水精鳞」的怪兽才能装备。装备怪兽的攻击力上升800。只要这张卡在场上存在，对方场上发动的魔法卡的效果无效。那之后，这张卡送去墓地。'),
(79206750, 'Abyss-scorn', '深渊蔑噬', 'アビスコーン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上1只名字带有「水精鳞」的怪兽才能发动。选择的怪兽的攻击力直到结束阶段时上升1000。此外，盖放的这张卡被送去墓地时，选择对方场上1只怪兽送去墓地。'),
(60202749, 'Abyss-sphere', '邃渊球惧', 'アビスフィアー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '从卡组把1只名字带有「水精鳞」的怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。此外，只要这张卡在场上存在，自己不能把魔法卡发动。这张卡从场上离开时，那只怪兽破坏。这张卡发动后，下次的对方的结束阶段时破坏。'),
(34707034, 'Abyss-squall', '深渊唤雨', 'アビスコール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地3只名字带有「水精鳞」的怪兽表侧守备表示特殊召唤。这个效果特殊召唤的怪兽效果无效化，不能攻击宣言，结束阶段时破坏。'),
(63941169, 'Abyss-steam', '邃渊结汽', 'アビスチーム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己抽出自己场上的鱼族·海龙族·水族怪兽的种族种类的数量。这张卡的发动后，直到下次的自己回合的结束时自己不是水属性怪兽不能从额外卡组特殊召唤。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的水属性怪兽被战斗·效果破坏的场合，把这张卡除外才能发动。自己的墓地·除外状态的1只「水精鳞」怪兽加入手卡。'),
(81878201, 'Abyss-sting Triaina', '邃渊突刺－三叉戟', 'アビスティング－トリアイナ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：从自己的手卡·墓地把1只「海皇」怪兽或「水精鳞」怪兽特殊召唤，把这张卡装备。 ②：装备怪兽被战斗·效果破坏的场合，可以作为代替把这张卡送去墓地。 ③：把墓地的这张卡除外，以自己的墓地·除外状态的最多3只鱼族·海龙族·水族怪兽为对象才能发动。那些怪兽回到卡组。'),
(97697447, 'Abyss-strom', '深渊激流', 'アビストローム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上表侧表示存在的「海」送去墓地才能发动。场上的魔法·陷阱卡全部送去墓地。'),
(89801755, 'Abyssal Designator', '深渊的指名者', '深淵の指名者', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '支付1000基本分。种族和属性各宣言一样。对方从手卡·卡组选取宣言的种族和属性2样1致的1张怪兽卡送去墓地。'),
(44223284, 'Abyssal Kingshark', '深海王 恶魔鲨', '深海王デビルシャーク', 'Effect Monster', 'Fish', 'WATER', 4, 1700, 600, '这张卡1回合只有1次不会被不指定对象的卡的效果破坏。'),
(17080584, 'Abyssrhine, the Atlantean Spirit', '海皇精 邃渊莱因', '海皇精 アビスライン', 'Effect Monster', 'Aqua', 'WATER', 3, 1600, 1600, '这个卡名在规则上也当作「水精鳞」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：把手卡的这张卡和自己的手卡·场上1只「海皇」怪兽或「水精鳞」怪兽解放才能发动。从卡组选1只7星的鱼族·海龙族·水族怪兽加入手卡或特殊召唤。这个回合，自己不是水属性怪兽不能从额外卡组特殊召唤。 ②：对方回合，把墓地的这张卡除外，把1张手卡丢弃去墓地才能发动。自己抽1张。'),
(9453320, 'Abysstrite, the Atlantean Spirit', '海皇精 邃渊里忒', '海皇精 アビストリーテ', 'XYZ Monster', 'Sea Serpent', 'WATER', 7, 2100, 2800, '水属性7星怪兽×2只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡超量召唤的场合，以自己墓地1只7星以下的鱼族·海龙族·水族怪兽为对象才能发动。那只怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，自己场上的水属性怪兽的攻击力·守备力上升这张卡的超量素材数量×300。 ③：把这张卡1个超量素材取除才能发动。从卡组把1张「深渊」陷阱卡在自己场上盖放。'),
(30983281, 'Accel Synchro Stardust Dragon', '加速同步・星尘龙', 'アクセルシンクロ・スターダスト・ドラゴン', 'Synchro Monster', 'Dragon', 'WIND', 8, 2500, 2000, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。从自己墓地把1只2星以下的调整特殊召唤。 ②：自己·对方的主要阶段，把这张卡解放才能发动。从额外卡组把1只「星尘龙」当作同调召唤作特殊召唤。那之后，进行1只同调怪兽的同调召唤。这个效果同调召唤的怪兽在这个回合不受对方发动的效果影响。'),
(37675907, 'Accel Synchron', '加速同步士', 'アクセル・シンクロン', 'Synchro Tuner Monster', 'Machine', 'DARK', 5, 500, 2100, '调整＋调整以外的怪兽1只以上 自己对「加速同调士」1回合只能有1次同调召唤。 ①：1回合1次，可以从卡组把1只「同调士」怪兽送去墓地，从以下效果选择1个发动。 ●这张卡的等级上升那只怪兽的等级数值。 ●这张卡的等级下降那只怪兽的等级数值。 ②：对方主要阶段才能发动（同一连锁上最多1次）。用包含这张卡的自己场上的怪兽为素材进行同调召唤。'),
(34838437, 'Accellight', '加速之光', 'アクセル・ライト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不能通常召唤。 ①：自己场上没有怪兽存在的场合才能发动。从卡组把4星以下的1只「光子」怪兽或者「银河」怪兽特殊召唤。'),
(86066372, 'Accesscode Talker', '访问码语者', 'アクセスコード・トーカー', 'Link Monster', 'Cyberse', 'DARK', NULL, 2300, NULL, '效果怪兽2只以上 对方不能对应这张卡的效果的发动把效果发动。 ①：这张卡连接召唤的场合，以那1只作为连接素材的连接怪兽为对象才能发动。这张卡的攻击力上升那只怪兽的连接标记数量×1000。 ②：从自己的场上·墓地把1只连接怪兽除外才能发动。对方场上1张卡破坏。这个回合，自己不能为让「访问码语者」的效果发动而把相同属性的怪兽除外。'),
(98444741, 'Accumulated Fortune', '积累的幸福', '積み上げる幸福', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '连锁4以后才能发动。从自己卡组抽2张卡。同1组连锁上有复数次同名卡的效果发动的场合，这张卡不能发动。'),
(10796448, 'Ace★Spades Speculation', 'A★黑桃之猜大小剑士', 'A★スペキュレーション', 'Fusion Monster', 'Warrior', 'LIGHT', 7, 2500, 2500, '攻击力2500以上的怪兽＋守备力2500以下的里侧守备表示怪兽 自己对「A★黑桃之猜大小剑士」1回合只能有1次特殊召唤。 ①：这张卡得到表示形式的以下效果。 ●攻击表示：这张卡的攻击力上升对方场上的怪兽的最高原本攻击力数值。 ●守备表示：这张卡不会被战斗·效果破坏。 ②：把1只攻击表示怪兽和1只里侧守备表示怪兽从自己场上解放才能发动。这张卡从墓地特殊召唤。'),
(98865920, 'Achacha Archer', '热辣辣弓手', 'アチャチャアーチャー', 'Effect Monster', 'Warrior', 'FIRE', 3, 1200, 600, '这张卡召唤·反转召唤成功时，给与对方基本分500分伤害。'),
(62476197, 'Achacha Chanbara', '热辣辣比剑者', 'アチャチャチャンバラー', 'Effect Monster', 'Warrior', 'FIRE', 3, 1400, 400, '给与基本分伤害的魔法·陷阱·效果怪兽的效果发动时才能发动。这张卡从手卡特殊召唤，给与对方基本分400分伤害。'),
(15808381, 'Achichi @Ignister', '热烫烫＠伊格尼斯者', 'アチチ＠イグニスター', 'Effect Monster', 'Cyberse', 'FIRE', 2, 800, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。除「辣辣妖@火灵天星」外的1只4星以下的「@火灵天星」怪兽从卡组加入手卡。 ②：自己的电子界族怪兽进行战斗的伤害步骤开始时，把墓地的这张卡除外才能发动。那只自己怪兽破坏。'),
(77568553, 'Acid Crawler', '酸液爬虫', 'アシッドクロウラー', 'Normal Monster', 'Insect', 'EARTH', 3, 900, 700, '巨大的青虫。吐出浓烈的酸液、可以溶解任何东西。'),
(21323861, 'Acid Rain', '酸性风暴', '酸の嵐', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '场上表侧表示存在的机械族怪兽全部破坏。'),
(41356845, 'Acid Trap Hole', '蓄积硫酸的落穴', '硫酸のたまった落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只里侧守备表示怪兽为对象才能发动。那只怪兽变成表侧守备表示，守备力是2000以下的场合破坏。守备力比2000高的场合回到里侧守备表示。'),
(35956022, 'Acidic Downpour', '酸雨', 'アシッドレイン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '全部地属性怪兽的攻击力下降500，守备力上升400。'),
(21051977, 'Acorno', '小矮人橡子', 'コロボックリ', 'Effect Monster', 'Plant', 'EARTH', 1, 200, 400, '自己的主要阶段时才能发动。从手卡把1只「松果小矮人」送去墓地，这张卡从手卡特殊召唤。'),
(47372349, 'Acrobat Monkey', '杂技猴', 'アクロバットモンキー', 'Normal Monster', 'Machine', 'EARTH', 3, 1000, 1800, '用超尖端技术所开发的猴子型自律机器人。行动像做杂技一般。'),
(33656832, 'Acrobatic Magician', '曲芸之魔术师', '曲芸の魔術師', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 5, 800, 2300, '①：魔法·陷阱卡的发动无效的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡被战斗破坏时才能发动。这张卡在自己的灵摆区域放置。'),
(35498188, 'Action Magic - Double Banking', '动作魔法-二重倾斜转弯', 'アクションマジック－ダブル・バンキング', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：丢弃1张手卡才能发动。自己场上的怪兽在这个回合战斗破坏对方怪兽的场合，只再1次可以继续攻击。 ②：这张卡在墓地存在的场合，自己主要阶段从手卡丢弃1张魔法卡才能发动。这张卡在自己的魔法与陷阱区域盖放。这个效果在这张卡送去墓地的回合不能发动。'),
(99004583, 'Action Magic - Full Turn', '动作魔法-最大U形转弯', 'アクションマジック－フルターン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：这个回合，怪兽之间的战斗发生的双方的战斗伤害变成2倍。 ②：这张卡在墓地存在的场合，自己主要阶段从手卡丢弃1张魔法卡才能发动。这张卡在自己的魔法与陷阱区域盖放。这个效果在这张卡送去墓地的回合不能发动。'),
(81555617, 'Ad Libitum of Despia', '惨绝戏之随兴凶剧', 'デスピアの凶劇', 'Effect Monster', 'Fairy', 'DARK', 8, 1500, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。场上的全部怪兽的攻击力直到对方回合结束时上升自身的等级×100。 ②：手卡·场上的这张卡成为融合召唤的素材，被送去墓地的场合或者被除外的场合，以「死狱乡的凶剧」以外的自己墓地·除外状态的1只「死狱乡」怪兽或者8星以上的融合怪兽为对象才能发动。那只怪兽特殊召唤。'),
(11302671, 'Adamancipator Analyzer', '魔救分析者', '魔救の分析者', 'Tuner Monster', 'Rock', 'EARTH', 4, 1500, 700, '这个卡名的①②的效果1回合各能使用1次。 ①：只有对方场上才有怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。从自己卡组上面把5张卡翻开。可以从那之中选1只调整以外的4星以下的岩石族怪兽特殊召唤。剩下的卡用喜欢的顺序回到卡组最下面。'),
(10286023, 'Adamancipator Crystal - Dragite', '魔救奇石－龙石', '魔救の奇石－ドラガイト', 'Effect Monster', 'Rock', 'WATER', 4, NULL, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用「魔救」卡的效果特殊召唤成功的场合才能发动。自己从卡组抽1张。 ②：这张卡在墓地存在的场合，以自己的场上·墓地1只水属性同调怪兽为对象才能发动。那只怪兽回到持有者的额外卡组，这张卡回到卡组最上面。'),
(47897376, 'Adamancipator Crystal - Leonite', '魔救奇石－狮石', '魔救の奇石－レオナイト', 'Effect Monster', 'Rock', 'FIRE', 4, NULL, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用「魔救」卡的效果特殊召唤成功的场合才能发动。从自己的手卡·墓地选1张「魔救」卡回到卡组最上面。 ②：这张卡在墓地存在的场合，以自己的场上·墓地1只炎属性同调怪兽为对象才能发动。那只怪兽回到持有者的额外卡组，这张卡回到卡组最上面。'),
(74891384, 'Adamancipator Crystal - Raptite', '魔救奇石－猛禽石', '魔救の奇石－ラプタイト', 'Effect Monster', 'Rock', 'WIND', 4, NULL, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用「魔救」卡的效果特殊召唤成功的场合才能发动。从自己的手卡·墓地选1只岩石族怪兽回到卡组最上面。 ②：这张卡在墓地存在的场合，以自己的场上·墓地1只风属性同调怪兽为对象才能发动。那只怪兽回到持有者的额外卡组，这张卡回到卡组最上面。'),
(99927991, 'Adamancipator Friends', '魔救奇缘', '魔救の奇縁', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上的岩石族怪兽数量＋5张从自己卡组上面翻开。可以从那之中选持有翻开的卡数量以下的等级的1只岩石族怪兽加入手卡。剩下的卡用喜欢的顺序回到卡组最下面。这张卡的发动后，直到回合结束时自己不是岩石族怪兽不能特殊召唤。'),
(46552140, 'Adamancipator Laputite', '魔救拉普达石', 'アダマシア・ラピュタイト', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己场上的岩石族怪兽的攻击力·守备力上升500。 ②：1回合1次，自己主要阶段才能发动。从卡组选最多5张「魔救」卡用喜欢的顺序在卡组最上面放置。'),
(9341993, 'Adamancipator Relief', '魔救救碎', '魔救の救砕', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上的「魔救」怪兽任意数量解放，以那个数量＋1张的场上的卡为对象才能发动。那些卡破坏。'),
(85914562, 'Adamancipator Researcher', '魔救探索者', '魔救の探索者', 'Tuner Monster', 'Rock', 'EARTH', 2, 100, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在，自己场上有「魔救之探索者」以外的岩石族怪兽存在的场合才能发动。这张卡特殊召唤。 ②：自己主要阶段才能发动。从自己卡组上面把5张卡翻开。可以从那之中选除调整外的1只4星以下的岩石族怪兽特殊召唤。剩余用喜欢的顺序回到卡组下面。'),
(45730592, 'Adamancipator Resonance', '魔救共振击', '魔救共振撃', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：自己场上有「魔救」同调怪兽存在，怪兽的效果发动时才能发动。那个发动无效并破坏。'),
(9464441, 'Adamancipator Risen - Dragite', '魔救奇迹－龙石', '魔救の奇跡－ドラガイト', 'Synchro Monster', 'Rock', 'WATER', 8, 3000, 2200, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从自己卡组上面把5张卡翻开。可以让最多有那之中的岩石族怪兽数量的对方场上的卡回到手卡。翻开的卡用喜欢的顺序回到卡组下面。 ②：自己墓地有水属性怪兽存在，对方把魔法·陷阱卡的效果发动时才能发动。那个发动无效并破坏。'),
(47674738, 'Adamancipator Risen - Leonite', '魔救奇迹－狮石', '魔救の奇跡－レオナイト', 'Synchro Monster', 'Rock', 'FIRE', 6, 2400, 2200, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从自己卡组上面把5张卡翻开。可以从那之中选1张「魔救」卡加入手卡。剩下的卡用喜欢的顺序回到卡组最下面。 ②：对方回合，自己墓地有炎属性怪兽存在的场合，以自己墓地1只岩石族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(73079836, 'Adamancipator Risen - Raptite', '魔救奇迹－猛禽石', '魔救の奇跡－ラプタイト', 'Synchro Monster', 'Rock', 'WIND', 6, 2200, 2800, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从自己卡组上面把5张卡翻开。可以从那之中选1只岩石族怪兽守备表示特殊召唤。剩下的卡用喜欢的顺序回到卡组最下面。 ②：对方回合，自己墓地有风属性怪兽存在的场合，以对方墓地1张卡为对象才能发动。那张卡除外。'),
(48519867, 'Adamancipator Seeker', '魔救追求者', '魔救の追求者', 'Tuner Monster', 'Rock', 'EARTH', 2, 1200, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「魔救之追求者」以外的「魔救」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。从自己卡组上面把5张卡翻开。可以从那之中选1只调整以外的4星以下的岩石族怪兽特殊召唤。剩下的卡用喜欢的顺序回到卡组最下面。'),
(72957245, 'Adamancipator Signs', '魔救气息', '魔救の息吹', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只岩石族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果把「魔救」怪兽特殊召唤的场合，可以再从卡组选1只4星以下的岩石族怪兽在卡组最上面放置。'),
(23812568, 'Additional Mirror Level 7', '附加镜・等级７', 'アディショナル・ミラー・レベル７', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己场上有7星怪兽特殊召唤的场合，从手卡·卡组把2张「附加镜·等级7」送去墓地，以那1只怪兽为对象才能发动。那2只同名怪兽从卡组特殊召唤。那之后，自己受到这个效果特殊召唤的怪兽的原本攻击力合计数值的伤害。这张卡的发动后，直到回合结束时自己只能有1次从额外卡组把怪兽特殊召唤。'),
(62325062, 'Adhesion Trap Hole', '黏着的落穴', '粘着落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方对怪兽的召唤·反转召唤·特殊召唤成功时才能发动。那怪兽只要在场上表侧表示存在，原本攻击力变成一半数值。'),
(53828396, 'Adhesive Explosive', '瞬着炸弹', '瞬着ボマー', 'Effect Monster', 'Machine', 'WIND', 3, 1000, 1000, '里侧守备表示的这张卡被对方怪兽攻击的场合，不进行伤害计算让这张卡变成攻击怪兽的装备卡。下次的对方回合的准备阶段时，那只装备怪兽破坏。'),
(94119480, 'Adreus, Keeper of Armageddon', '终焉守护者 阿德琉斯', '終焉の守護者アドレウス', 'XYZ Monster', 'Fiend', 'DARK', 5, 2600, 1700, '5星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以对方场上1张表侧表示卡为对象才能发动。那张卡破坏。'),
(15464375, 'Adularia of the June Moon', '水月之冰长石巫', '水月のアデュラリア', 'Effect Monster', 'Spellcaster', 'WATER', 5, 1000, 1000, '这个卡名的①的方法的特殊召唤1回合只能有1次，③的效果1回合只能使用1次。 ①：自己的魔法与陷阱区域有表侧表示卡存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡的攻击力·守备力上升场上的表侧表示的魔法·陷阱卡数量×600。 ③：把自己的魔法与陷阱区域2张表侧表示卡送去墓地才能发动。从卡组把1只4星以下的怪兽送去墓地。'),
(51630558, 'Advance Draw', '上级抽卡', 'アドバンスドロー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上表侧表示存在的1只8星以上的怪兽解放发动。从自己卡组抽2张卡。'),
(38589847, 'Advance Force', '上级召唤力', 'アドバンス・フォース', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，7星以上的怪兽可以把1只5星以上的怪兽解放作上级召唤。'),
(76224717, 'Advance Zone', '上级进化区', 'アドバンス・ゾーン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，自己对怪兽的上级召唤成功的回合的结束阶段时才能发动。这个回合自己为上级召唤而解放的怪兽数量的以下效果适用。 ●1只以上：选对方场上盖放的1张卡破坏。 ●2只以上：从卡组抽1张卡。 ●3只以上：选自己墓地1只怪兽加入手卡。'),
(18847598, 'Advanced Crystal Beast Amber Mammoth', '高等宝玉兽 琥珀猛犸', 'A宝玉獣 アンバー・マンモス', 'Effect Monster', 'Beast', 'EARTH', 4, 1700, 1600, '①：场地区域没有「高等暗黑结界」存在的场合这只怪兽送去墓地。 ②：1回合1次，以自己的「高等宝玉兽」卡或者自己的「高等暗黑结界」为对象的效果由对方发动时才能发动。那个发动无效。 ③：1回合1次，自己的「高等宝玉兽」怪兽被选择作为攻击对象时才能发动。那次攻击无效。 ④：表侧表示的这张卡在怪兽区域被破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(19963185, 'Advanced Crystal Beast Amethyst Cat', '高等宝玉兽 紫晶猫', 'A宝玉獣 アメジスト・キャット', 'Effect Monster', 'Beast', 'EARTH', 3, 1200, 400, '①：场地区域没有「高等暗黑结界」存在的场合这只怪兽送去墓地。 ②：自己的「高等宝玉兽」怪兽可以直接攻击。那次直接攻击给与对方的战斗伤害变成一半。 ③：表侧表示的这张卡在怪兽区域被破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(45236142, 'Advanced Crystal Beast Cobalt Eagle', '高等宝玉兽 钴尖晶鹰', 'A宝玉獣 コバルト・イーグル', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1400, 800, '①：场地区域没有「高等暗黑结界」存在的场合这只怪兽送去墓地。 ②：把手卡·场上的这张卡送去墓地才能发动。从卡组把1张「高等暗黑结界」加入手卡。 ③：1回合1次，以自己场上1张「高等宝玉兽」卡为对象才能发动。那张卡回到持有者手卡或回到卡组最上面。 ④：表侧表示的这张卡在怪兽区域被破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(46358784, 'Advanced Crystal Beast Emerald Tortoise', '高等宝玉兽 翠玉龟', 'A宝玉獣 エメラルド・タートル', 'Effect Monster', 'Aqua', 'WATER', 3, 600, 2000, '①：场地区域没有「高等暗黑结界」存在的场合这只怪兽送去墓地。 ②：1回合1次，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的表示形式变更。这个效果在对方回合也能发动。 ③：表侧表示的这张卡在怪兽区域被破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(83575471, 'Advanced Crystal Beast Ruby Carbuncle', '高等宝玉兽 红玉兽', 'A宝玉獣 ルビー・カーバンクル', 'Effect Monster', 'Fairy', 'LIGHT', 3, 300, 300, '这个卡名的③的效果1回合只能使用1次。 ①：场地区域没有「高等暗黑结界」存在的场合这只怪兽送去墓地。 ②：表侧表示的这张卡在怪兽区域被破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。 ③：这张卡是当作永续魔法卡使用的场合才能发动。这张卡特殊召唤。那之后，可以把自己的魔法与陷阱区域的「高等宝玉兽」怪兽卡尽可能特殊召唤。'),
(71620241, 'Advanced Crystal Beast Sapphire Pegasus', '高等宝玉兽 青玉飞马', 'A宝玉獣 サファイア・ペガサス', 'Effect Monster', 'Beast', 'WIND', 4, 1800, 1200, '①：场地区域没有「高等暗黑结界」存在的场合这只怪兽送去墓地。 ②：这张卡召唤·反转召唤·特殊召唤成功的场合才能发动。从自己的手卡·卡组·墓地的怪兽以及除外的自己怪兽之中选1只「高等宝玉兽」怪兽当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。 ③：表侧表示的这张卡在怪兽区域被破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(72843899, 'Advanced Crystal Beast Topaz Tiger', '高等宝玉兽 黄玉虎', 'A宝玉獣 トパーズ・タイガー', 'Effect Monster', 'Beast', 'EARTH', 4, 1600, 1000, '①：场地区域没有「高等暗黑结界」存在的场合这只怪兽送去墓地。 ②：只要这张卡在怪兽区域存在，自己场上的「高等宝玉兽」怪兽的攻击力·守备力上升400，对方场上的怪兽的攻击力·守备力下降400。 ③：表侧表示的这张卡在怪兽区域被破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(12644061, 'Advanced Dark', '高等暗黑结界', 'アドバンスド・ダーク', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的「宝玉兽」怪兽以及墓地的「宝玉兽」怪兽全部变成暗属性。 ②：只要这张卡在场地区域存在，成为「究极宝玉神」怪兽的攻击对象的怪兽的效果只在那次战斗阶段内无效化。 ③：自己的「宝玉兽」怪兽的战斗要让自己受到战斗伤害的伤害计算时，从卡组把1只「宝玉兽」怪兽送去墓地才能发动。那次战斗发生的对自己的战斗伤害变成0。'),
(61314842, 'Advanced Heraldry Art', '高等徽章术', '高等紋章術', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地2只「纹章兽」怪兽为对象才能发动。那2只怪兽特殊召唤，只用那2只为素材进行超量召唤。'),
(46052429, 'Advanced Ritual Art', '高等仪式术', '高等儀式術', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '①：等级合计直到变成和仪式召唤的怪兽相同为止，把卡组的通常怪兽送去墓地，从手卡把1只仪式怪兽仪式召唤。'),
(10678778, 'Aegaion the Sea Castrum', '魔海城 埃该翁', '魔海城アイガイオン', 'XYZ Monster', 'Machine', 'WATER', 8, -1, 3000, '8星怪兽×2 「魔海城 埃该翁」的①②的效果1回合各能使用1次，对方回合也能发动。 ①：从对方的额外卡组把里侧表示的怪兽随机1只除外。这张卡的攻击力变成和除外的怪兽的攻击力相同。 ②：把这张卡1个超量素材取除，以除外的1只对方的融合·同调·超量怪兽为对象才能发动。那只怪兽回到额外卡组，选和那只怪兽相同种类（融合·同调·超量）的对方场上1只怪兽破坏。'),
(47060347, 'Aegis of Gaia', '女神的加护', '女神の加護', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己回复3000基本分。自己场上表侧表示存在的这张卡从场上离开时，自己受到3000分伤害。'),
(7935043, 'Aegis of the Ocean Dragon Lord', '海龙神的加护', '海竜神の加護', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '直到这个回合的结束阶段时，自己场上表侧表示存在的3星以下的水属性怪兽不会被战斗以及卡的效果破坏。'),
(28143384, 'Aerial Eater', '大气吞食者', 'エアリアル・イーター', 'Fusion Monster', 'Fiend', 'WIND', 6, 2100, 2600, '相同属性的恶魔族怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡融合召唤的场合才能发动。从卡组把1只恶魔族怪兽送去墓地。 ②：这张卡在墓地存在的场合，把除「大气吸收者」外的2只6星以上而相同属性的恶魔族怪兽从自己墓地除外才能发动。这张卡特殊召唤。'),
(70875955, 'Aerial Recharge', '空中补给', '空中補給', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的控制者在每次双方的结束阶段把自己场上1只衍生物或者「幻兽机」怪兽解放。或者都不解放让这张卡送去墓地。 ①：1回合1次，可以发动。在自己场上把1只「幻兽机衍生物」（机械族·风·3星·攻/守0）特殊召唤。'),
(83094004, 'Aeropixthree', '健美操妖精Ξ', 'エアロピΞ', 'Tuner Monster', 'Fairy', 'WIND', 1, 200, 200, '①：1回合1次，以和这张卡相同纵列1只对方的表侧表示怪兽为对象才能发动。自己场上的这张卡的位置向其他的自己的主要怪兽区域移动，作为对象的对方怪兽的位置向这张卡的正对面的对方的主要怪兽区域移动。那之后，给那只对方怪兽放置1个燃烧指示物。这个效果在对方回合也能发动。 ②：只要这张卡在怪兽区域存在，有燃烧指示物放置的怪兽的攻击力·守备力下降那数量×200。'),
(56804361, 'Aether, the Empowering Dragon', '魔装圣龙 以太神兵龙', '魔装聖龍 イーサルウェポン', 'Effect Monster', 'Dragon', 'LIGHT', 6, 2300, 1600, '「魔装圣龙 以太神兵龙」的效果1回合只能使用1次。 ①：这张卡灵摆召唤成功时，以场上1张卡为对象才能发动。那张卡回到持有者手卡。'),
(28865322, 'Aether, the Evil Empowering Dragon', '魔装邪龙 以太神兵龙', '魔装邪龍 イーサルウェポン', 'Pendulum Effect Monster', 'Dragon', 'DARK', 6, 2300, 1600, '①：这张卡召唤·特殊召唤成功时，以场上1只怪兽为对象才能发动。那只怪兽除外。'),
(82263578, 'After the Storm', '战火的残渣', '戦火の残滓', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：双方场上没有其他卡存在的场合，以自己墓地1只水·风属性怪兽为对象才能发动。那只水·风属性怪兽加入手卡。'),
(25345186, 'After the Struggle', '灭绝战争', 'ジェノサイド・ウォー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '只能在主要阶段一发动。这个回合经过了战斗伤害计算的自己·对方怪兽在结束步骤时全部破坏。'),
(43575579, 'Afterglow', '残照', 'アフター・グロー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在决斗中只能发动1张。 ①：从自己的手卡·卡组·墓地以及自己场上的表侧表示的卡之中把包含这张卡的「残照」全部除外。那之后，从除外的自己的卡之中选1张「残照」加入卡组。下次的自己抽卡阶段，通常抽卡的卡给双方确认。那是「残照」的场合，给与对方4000伤害。'),
(64952266, 'Against the Wind', '逆风', 'アゲインスト・ウィンド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地存在的1只名字带有「黑羽」的怪兽发动。自己受到那只怪兽的攻击力数值的伤害，那只怪兽加入手卡。'),
(2411269, 'Agave Dragon', '龙绝兰', '竜絶蘭', 'Link Monster', 'Wyrm', 'EARTH', NULL, 3000, NULL, '衍生物以外的怪兽2只以上 这个卡名的效果1回合只能使用1次。 ①：这张卡连接召唤成功的场合才能发动。双方墓地的怪兽的种族和那数量对应的以下效果适用。 ●龙族：给与对方那个数量×100伤害。 ●恐龙族：这张卡的攻击力上升那个数量×200。 ●海龙族：对方场上的全部怪兽的攻击力下降那个数量×300。 ●幻龙族：自己回复那个数量×400基本分。'),
(27822206, 'Ages of Stars and Frost', '几星霜', '幾星霜', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的怪兽被自己的魔法卡的效果或者对方的效果破坏送去墓地的回合才能发动。下次的自己战斗阶段可以进行2次。 ②：这张卡在墓地存在的状态，自己场上的怪兽回到卡组·额外卡组（里侧）的场合才能发动。这张卡加入手卡。'),
(16135253, 'Agido', '阿基多', 'アギド', 'Effect Monster', 'Fairy', 'EARTH', 4, 1500, 1300, '这张卡被战斗破坏送去墓地时，掷1次骰子。可以从自己的墓地中特殊召唤1只等级与掷出点数相同的天使族怪兽上场。（若掷出6，则包括6星以上的怪兽）。'),
(62320425, 'Agido the Ancient Sentinel', '古卫兵 阿基多', '古衛兵アギド', 'Effect Monster', 'Fairy', 'EARTH', 4, 1500, 1300, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡·卡组有卡被送去对方墓地的场合才能发动。这张卡从手卡特殊召唤。那之后，可以从自己墓地选「古卫兵 阿基多」以外的1只天使族·地属性·4星怪兽特殊召唤。 ②：这张卡从手卡·卡组送去墓地的场合才能发动。从双方卡组上面把5张卡送去墓地。那之后，自己墓地有「现世与冥界的逆转」存在的场合，可以从自己或者对方的卡组上面把5张卡送去墓地。'),
(13014905, 'Agnimal Candle', '火天兽－蜡烛', '火天獣－キャンドル', 'Tuner Monster', 'Pyro', 'FIRE', 4, 1700, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡用抽卡以外的方法加入手卡的场合才能发动。这张卡特殊召唤。 ②：1回合最多3次，怪兽被送去自己墓地的场合才能发动（同一连锁上最多1次）。这张卡的等级上升或下降1星。'),
(86377375, 'Ahrima, the Wicked Warden', '恶王 阿赫里曼', '悪王アフリマ', 'Effect Monster', 'Fiend', 'DARK', 4, 1700, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：把这张卡从手卡丢弃才能发动。从卡组把1张「黯黑世界-暗影敌托邦-」加入手卡。 ②：把自己场上1只暗属性怪兽解放才能发动。自己从卡组抽1张。为这个效果发动而把这张卡以外的暗属性怪兽解放的场合，可以作为抽卡的代替而从卡组把1只守备力2000以上的暗属性怪兽加入手卡。'),
(96084564, 'Aileron', '埃尔隆', 'エルロン', 'Effect Monster', 'Machine', 'WIND', 1, NULL, NULL, '这个卡名在规则上也当作「闪刀」卡使用。这个卡名的①③的效果1回合只能有1次使用其中任意1个。 ①：自己·对方的主要阶段，以自己场上1只「闪刀姬」怪兽为对象才能发动。从自己的手卡·场上把这张卡当作装备魔法卡使用给那只怪兽装备。 ②：有这张卡装备的「闪刀姬」怪兽的攻击力上升400。 ③：场上的这张卡被破坏的场合才能发动。从卡组把1张「闪刀」魔法卡送去墓地。'),
(69023354, 'Air Armor Ninja', '机甲忍者 风', '機甲忍者エアー', 'Effect Monster', 'Warrior', 'WIND', 4, 1400, 1400, '这张卡召唤·反转召唤·特殊召唤成功时，选择自己场上1只名字带有「忍者」的怪兽才能发动。选择的怪兽的等级下降1星。'),
(98864751, 'Air Cracking Storm', '空气解密风暴', 'エアークラック・ストーム', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '机械族怪兽才能装备。 ①：装备怪兽的攻击破坏对方怪兽时才能发动。这次战斗阶段中，装备怪兽只再1次可以攻击。这个效果发动的回合，装备怪兽以外的自己怪兽不能攻击。'),
(8353769, 'Air Eater', '空气吸收者', 'エア・イーター', 'Normal Monster', 'Fiend', 'WIND', 6, 2100, 1600, '吸收周围的空气，使对方窒息的妖怪。'),
(18036057, 'Airknight Parshath', '天空骑士 珀耳修斯', '天空騎士パーシアス', 'Effect Monster', 'Fairy', 'LIGHT', 5, 1900, 1400, '①：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ②：这张卡给与对方战斗伤害的场合发动。自己从卡组抽1张。'),
(84747429, 'Airorca', '空邪鲸', 'エアジャチ', 'Effect Monster', 'Sea Serpent', 'WIND', 3, 1400, 300, '1回合1次，可以从手卡把1只鱼族·海龙族·水族怪兽从游戏中除外，选择对方场上表侧表示存在的1张卡破坏。那之后，这张卡直到下次的自己的准备阶段时从游戏中除外。'),
(48202661, 'Aitsu', '彼者', 'アイツ', 'Normal Monster', 'Fairy', 'FIRE', 5, 100, 100, '虽然样子不可靠，其实隐藏着惊人的潜在能力。'),
(35877582, 'Aiwass, the Magistus Spell Spirit', '伟魔圣灵 法典之爱华斯', '法典の守護者アイワス', 'Fusion Monster', 'Fiend', 'WIND', 8, 2000, 2800, '「大贤者」怪兽＋魔法师族怪兽 这个卡名的①的效果1回合只能使用1次。 ①：自己·对方的主要阶段，以这张卡以外的场上1只表侧表示怪兽为对象才能发动。自己场上的这张卡当作装备卡使用给那只怪兽装备。这个效果把这张卡给对方怪兽装备的场合，装备怪兽的效果不能发动，得到那个控制权。 ②：有这张卡装备的怪兽的攻击力·守备力上升1000。'),
(63378869, 'Aiza the Dragoness of Deranged Devotion', '狂爱之龙娘 相樱', '狂愛の竜娘アイザ', 'Effect Monster', 'Dragon', 'FIRE', 4, 1500, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。给对方场上1只表侧表示怪兽放置1个狂爱指示物。有狂爱指示物放置的怪兽不能作为融合·同调·超量·连接召唤的素材。 ②：有狂爱指示物放置的对方怪兽和这张卡进行战斗的伤害步骤开始时才能发动。那只对方怪兽破坏，双方受到那个原本攻击力数值的伤害。这张卡在那次战斗阶段结束时破坏。'),
(38035986, 'Akakieisu', '红A', 'レッド・エース', 'Normal Monster', 'Spellcaster', 'DARK', 3, 1000, 800, '施放死亡诅咒的魔法师。听到咒文的敌人将变得神智不清。'),
(28776350, 'Akashic Magician', '阿卡西魔术师', 'アカシック・マジシャン', 'Link Monster', 'Spellcaster', 'DARK', NULL, 1700, NULL, '衍生物以外的相同种族的怪兽2只 自己对「虚空俏丽魔术师」1回合只能有1次连接召唤。 ①：这张卡连接召唤成功的场合发动。这张卡所连接区的怪兽全部回到持有者手卡。 ②：1回合1次，宣言1个卡名才能发动。把这张卡所互相连接区的怪兽的连接标记合计数量的卡从自己卡组上面翻开，那之中有宣言的卡的场合，那卡加入手卡。那以外的翻开的卡全部送去墓地。'),
(36904469, 'Akihiron', '卡可塔斯', 'カクタス', 'Normal Monster', 'Aqua', 'WATER', 5, 1700, 1400, '潜在水中形状不明的怪兽。'),
(38837163, 'Akz, the Pumer', '豹人', 'ピューマン', 'Effect Monster', 'Beast-Warrior', 'EARTH', 6, 1500, 1000, '这张卡不能通常召唤。把自己墓地存在的2只兽战士族怪兽从游戏中除外的场合可以特殊召唤。1回合1次，可以从手卡丢弃1只兽战士族怪兽，从以下效果选择1个发动。 ●这张卡的攻击力直到结束阶段时变成2倍。 ●这个回合这张卡可以直接攻击对方玩家。'),
(25795273, 'Al-Lumi''raj', '光幻独角兔', 'イルミラージュ', 'Tuner Monster', 'Wyrm', 'WIND', 3, 1600, 1000, '①：只要这张卡在怪兽区域存在，场上的怪兽的攻击力·守备力下降那怪兽的等级或者阶级×300。'),
(3410461, 'Alba-Lenatus the Abyss Dragon', '深渊龙 阿尔白・雷纳图斯', '深淵竜アルバ・レナトゥス', 'Fusion Monster', 'Dragon', 'DARK', 8, 2500, 2500, '「阿不思的落胤」＋龙族怪兽1只以上 这张卡不能作为融合素材。这张卡用融合召唤以及以下方法才能特殊召唤。 ●把自己·对方的怪兽区域的上记的卡送去墓地的场合可以从额外卡组特殊召唤。 ①：这张卡在同1次的战斗阶段中可以向怪兽作出最多有作为这张卡的融合素材的怪兽数量的攻击。 ②：这张卡被送去墓地的回合的结束阶段才能发动。从卡组把1张「融合」通常魔法卡加入手卡。'),
(37683547, 'Albaz the Ashen', '灰烬的阿尔白斯', '灰燼のアルバス', 'Effect Monster', 'Dragon', 'DARK', 4, 1800, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「阿不思的落胤」使用。 ②：只要自己墓地有8星融合怪兽存在，这张卡的攻击力上升自己墓地的怪兽数量×200，对方不能把自己场上的其他的怪兽作为效果的对象。 ③：这张卡和融合怪兽在自己墓地存在的状态，自己场上的怪兽因对方的效果从场上离开的场合才能发动。这张卡特殊召唤。'),
(87746184, 'Albion the Branded Dragon', '烙印龙 阿尔比昂', '烙印竜アルビオン', 'Fusion Monster', 'Dragon', 'DARK', 8, 2500, 2000, '「阿不思的落胤」＋光属性怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡融合召唤的场合才能发动。自己的手卡·场上·墓地的怪兽作为融合素材除外，把除「烙印龙 白界龙」外的1只8星以下的融合怪兽融合召唤。 ②：这张卡被送去墓地的回合的结束阶段才能发动。从卡组选1张「烙印」魔法·陷阱卡加入手卡或在自己场上盖放。'),
(38811586, 'Albion the Sanctifire Dragon', '真炎龙 阿尔比昂', '真炎竜アルビオン', 'Fusion Monster', 'Dragon', 'LIGHT', 8, 3000, 2500, '「阿不思的落胤」＋魔法师族·光属性怪兽 这张卡不能作为融合素材。这个卡名的②③的效果1回合各能使用1次。 ①：对方不能把场上的这张卡作为效果的对象。 ②：对方回合，以自己·对方的墓地的怪兽合计2只为对象才能发动。那些怪兽在双方场上各1只特殊召唤。 ③：这张卡在墓地存在的场合才能发动。额外怪兽区域以及双方的中央的主要怪兽区域存在的4只怪兽解放，这张卡特殊召唤。'),
(25451383, 'Albion the Shrouded Dragon', '黑衣龙 阿尔比昂', '黒衣竜アルビオン', 'Effect Monster', 'Dragon', 'DARK', 8, 2500, 2000, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「阿不思的落胤」使用。 ②：这张卡在手卡·墓地存在的场合，把1只「阿不思的落胤」或1张「烙印」魔法·陷阱卡从手卡·卡组送去墓地才能发动。以那张卡从哪里送去墓地来对应的以下效果适用。 ●手卡：这张卡特殊召唤。 ●卡组：这张卡回到卡组最下面。从手卡回去的场合，再让自己抽1张。'),
(65301952, 'Alchemic Magician', '炼金魔术师', 'アルケミック・マジシャン', 'XYZ Monster', 'Spellcaster', 'DARK', 4, 1500, 1500, '魔法师族4星怪兽×3 这张卡的攻击力上升自己墓地的魔法卡数量×200的数值。此外，自己的结束阶段时1次，把这张卡1个超量素材取除，把1张手卡送去墓地才能发动。从卡组选1张魔法卡，在自己的魔法与陷阱卡区域盖放。'),
(78121572, 'Alchemist of Black Spells', '黑魔力精制者', '黒魔力の精製者', 'Effect Monster', 'Spellcaster', 'WIND', 4, 1200, 1800, '1回合1次，可以把自己场上表侧攻击表示存在的这张卡变更为表侧守备表示，并给自己场上表侧表示存在的1张可以放置魔力指示物的卡放置1个魔力指示物。');